package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathIntrospector;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyPointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for PropertyPointer.getLength()
 */
public class PropertyPointer_getLength_TriageGen1Test {

    private NodePointer mockParent;
    private PropertyPointer propertyPointer;

    @Before
    public void setUp() {
        mockParent = mock(NodePointer.class);
        // PropertyPointer is abstract in the provided signature (due to abstract methods), 
        // but we need an instance to test getLength(). 
        // Since getLength() calls getBaseValue(), we must mock the behavior of the concrete implementation.
        propertyPointer = Mockito.spy(new PropertyPointer(mockParent) {
            @Override
            public abstract String getPropertyName();
            @Override
            public abstract void setPropertyName(String propertyName);
            @Override
            public abstract int getPropertyCount();
            @Override
            public abstract String[] getPropertyNames();
            @Override
            protected abstract boolean isActualProperty();
        });
    }

    /**
     * Test getLength() when the base value is a String of length 5.
     */
    @Test
    public void testGetLength_StringValue() {
        String testValue = "Hello";
        // We must mock getBaseValue() because getLength() relies on it.
        // Note: getBaseValue() is likely a protected method in the parent class.
        doReturn(testValue).when(propertyPointer).getBaseValue();

        int result = propertyPointer.getLength();

        assertEquals(5, result);
    }

    /**
     * Test getLength() when the base value is an Array of length 3.
     */
    @Test
    public void testGetLength_ArrayValue() {
        Object[] testArray = new Object[]{new Object(), new Object(), new Object()};
        doReturn(testArray).when(propertyPointer).getBaseValue();

        int result = propertyPointer.getLength();

        assertEquals(3, result);
    }

    /**
     * Test getLength() when the base value is a List of length 2.
     */
    @Test
    public void testGetLength_ListValue() {
        java.util.List<String> testList = java.util.Arrays.asList("A", "B");
        doReturn(testList).when(propertyPointer).getBaseValue();

        int result = propertyPointer.getLength();

        assertEquals(2, result);
    }

    /**
     * Test getLength() when the base value is null.
     * Depending on ValueUtils implementation, this usually returns 0 or throws exception.
     * Assuming ValueUtils returns 0 for null.
     */
    @Test
    public void testGetLength_NullValue() {
        doReturn(null).when(propertyPointer).getBaseValue();

        int result = propertyPointer.getLength();

        assertEquals(0, result);
    }

    /**
     * Test getLength() when the base value is an empty collection.
     */
    @Test
    public void testGetLength_EmptyCollection() {
        java.util.List<Object> emptyList = java.util.Collections.emptyList();
        doReturn(emptyList).when(propertyPointer).getBaseValue();

        int result = propertyPointer.getLength();

        assertEquals(0, result);
    }

    /**
     * Test getLength() when the base value is an Integer (not a collection/array/string).
     * Usually, ValueUtils returns 1 or 0 for non-collection objects. 
     * Assuming it returns 0 for non-length-bearing objects.
     */
    @Test
    public void testGetLength_NonCollectionObject() {
        doReturn(123).when(propertyPointer).getBaseValue();

        int result = propertyPointer.getLength();

        // Assuming ValueUtils handles non-collection objects by returning 0
        assertEquals(0, result);
    }
}
